def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        return 'C'
    if n < 6:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    op = [h[1] for h in history]
    my = [h[0] for h in history]
    last_opp = op[-1]
    last_my = my[-1]

    # recent window counts
    def dcount(seq):
        c = 0
        for x in seq:
            if x == 'D':
                c += 1
        return c

    opp_c_total = n - dcount(op)
    opp_d_total = n - opp_c_total

    # Near-final stretch
    if n >= 90:
        recent10 = op[-10:]
        d10 = dcount(recent10)
        if d10 >= 3:
            return 'D'
        if d10 == 0:
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Strong defector: punish
    if n >= 12 and opp_d_total * 3 > n * 2 and dcount(op[-8:]) >= 5:
        if rng.random() < 0.08:
            return 'C'
        return 'D'

    # Very cooperative opponent early-mid: cooperate, probe rarely
    if opp_d_total == 0 and n >= 6:
        if n % 23 == 0:
            return 'D'
        return 'C'

    # Mostly cooperative opponent
    if n >= 10 and opp_d_total * 10 <= n:
        last8 = op[-8:]
        d8 = dcount(last8)
        if d8 == 0:
            if n % 19 == 0:
                return 'D'
            return 'C'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Tit-for-tat core with forgiveness on long mutual defection
    if last_opp == 'D':
        if last_my == 'D':
            run_dd = 0
            i = n - 1
            while i >= 0 and op[i] == 'D' and my[i] == 'D':
                run_dd += 1
                i -= 1
            if run_dd >= 4 and rng.random() < 0.3:
                return 'C'
            return 'D'
        # Opponent exploited our cooperation
        recent = op[-5:]
        if dcount(recent) >= 3:
            return 'D'
        if rng.random() < 0.12:
            return 'C'
        return 'D'

    # Opponent just cooperated
    if last_my == 'D':
        d5 = dcount(op[-5:])
        if d5 >= 3:
            return 'D'
        return 'C'
    # Both cooperated
    if n >= 20:
        recent12 = op[-12:]
        if dcount(recent12) == 0:
            if n % 17 == 0:
                return 'D'
            return 'C'
    return 'C'
